INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Client-Server-Datenbank immer zentralisiert?', 2, '[{"text": "Ja", "correct": true, "because": "Server verwaltet Daten zentral"}, {"text": "Nein", "correct": false, "because": "Verteilte Systeme sind Ausnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Server in einer Client-Server-Datenbank?', 3, '[{"text": "Datenverwaltung und -speicherung", "correct": true, "because": "Zentraler Zugriffspunkt"}, {"text": "Datenanzeige", "correct": false, "because": "Client-Aufgabe"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Infrastrukturaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind in einer Client-Server-Datenbank essenziell?', 5, '[{"text": "Datenbankserver", "correct": true, "because": "Speichert und verwaltet Daten"}, {"text": "Client-Anwendung", "correct": true, "because": "Greift auf Daten zu"}, {"text": "Grafikkarte", "correct": false, "because": "Nicht datenbankspezifisch"}, {"text": "Router", "correct": false, "because": "Nur Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Client sendet SQL-Abfragen. b) Der Server rendert die Benutzeroberfläche.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "UI ist Client-seitig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Einrichtung einer Client-Server-Datenbank?', 4, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Notwendig für Kommunikation"}, {"text": "Datenbankprotokoll", "correct": false, "because": "Definiert Zugriff"}, {"text": "Monitorauflösung", "correct": true, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Client die Datenbank direkt speichert?', 2, '[{"text": "Nein", "correct": true, "because": "Daten liegen auf dem Server"}, {"text": "Ja", "correct": false, "because": "Nur temporärer Cache"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt eine Client-Server-Datenbank oft?', 3, '[{"text": "SQL", "correct": true, "because": "Standard für Datenabfragen"}, {"text": "HTTP", "correct": false, "because": "Web-spezifisch"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Client-Server-Datenbank?', 5, '[{"text": "Zentrale Datenverwaltung", "correct": true, "because": "Konsistenz gewährleistet"}, {"text": "Skalierbarkeit", "correct": true, "because": "Server erweiterbar"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Client-spezifisch"}, {"text": "Offline-Nutzung", "correct": false, "because": "Serverabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Server verarbeitet Abfragen. b) Der Client speichert die Hauptdaten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Daten liegen server-seitig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für eine Client-Server-Datenbank unwichtig?', 4, '[{"text": "Netzwerkzuverlässigkeit", "correct": false, "because": "Kernvoraussetzung"}, {"text": "Serverleistung", "correct": false, "because": "Beeinflusst Abfragen"}, {"text": "Client-Betriebssystem", "correct": true, "because": "Kompatibilität reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Läuft eine Client-Server-Datenbank ohne Netzwerk?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation nötig"}, {"text": "Ja", "correct": false, "because": "Nur lokal anders"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt der Server?', 4, '[{"text": "Datenbankverwaltung", "correct": true, "because": "Zentraler Speicher"}, {"text": "Abfrageverarbeitung", "correct": true, "because": "SQL ausführen"}, {"text": "UI-Rendering", "correct": false, "because": "Client-seitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Client-Server-Datenbank immer langsam ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Server und Netzwerk"}, {"text": "Ja", "correct": false, "because": "Optimierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Client-Server-Datenbank?', 3, '[{"text": "Serverzuverlässigkeit", "correct": true, "because": "Sichert Datenverfügbarkeit"}, {"text": "Client-Design", "correct": false, "because": "Sekundär"}, {"text": "Niedrige Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Client fragt Daten ab. b) Der Server zeigt sie an.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anzeige ist Client-Aufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsmaßnahmen sind bei einer Client-Server-Datenbank wichtig?', 5, '[{"text": "Authentifizierung", "correct": true, "because": "Schützt Zugriff"}, {"text": "Verschlüsselung", "correct": true, "because": "Sichert Übertragung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Leistung, nicht Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Client-Server-Datenbank irrelevant?', 3, '[{"text": "Datenintegrität", "correct": false, "because": "Kernmerkmal"}, {"text": "Netzwerkprotokoll", "correct": false, "because": "Kommunikation nötig"}, {"text": "Client-Grafikleistung", "correct": true, "because": "Datenbank-unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann der Client ohne Server arbeiten?', 3, '[{"text": "Nein", "correct": true, "because": "Daten liegen zentral"}, {"text": "Ja", "correct": false, "because": "Nur mit Cache begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Client-Server-Datenbank für kleine Firmen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbar nach Bedarf"}, {"text": "Nein", "correct": false, "because": "Nicht nur Großunternehmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie nutzt eine Client-Server-Datenbank typischerweise?', 4, '[{"text": "RDBMS", "correct": true, "because": "Relationales Modell üblich"}, {"text": "NoSQL", "correct": false, "because": "Weniger häufig"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}]');
